#include <iostream>
#include <vector>
#include <numeric>
#include <iterator>
#include <algorithm>

int main() {
    // Khoi tao vector voi danh sach khoi tao C++11
    std::vector<int> numbers{10, 20, 30, 40, 50};

    std::cout << "Kich thuoc ban dau: " << numbers.size() 
              << ", dung luong: " << numbers.capacity() << "\n";

    // Xuat vector theo thu tu nguoc dung crbegin va crend
    std::cout << "Duyet nguoc: ";
    for (auto it = numbers.crbegin(); it != numbers.crend(); ++it) {
        std::cout << *it << ' ';
    }
    std::cout << "\n";

    // Mo rong dung luong roi thu hoi
    numbers.reserve(100);
    std::cout << "Dung luong sau reserve(100): " << numbers.capacity() << "\n";

    numbers.shrink_to_fit();
    std::cout << "Dung luong sau shrink_to_fit(): " << numbers.capacity() << "\n";

    // Xuat qua ostream_iterator va std::copy
    std::cout << "Xuat qua std::copy: ";
    std::ostream_iterator<int> out(std::cout, " ");
    std::copy(numbers.cbegin(), numbers.cend(), out);
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <array>
#include <algorithm>
#include <iterator>
#include <stdexcept>

int main() {
    std::array<int, 6> initialValues{1, 2, 3, 4, 5, 6};
    std::vector<int> integers(initialValues.cbegin(), initialValues.cend());
    std::ostream_iterator<int> out(std::cout, " ");

    std::cout << "Vector ban dau: ";
    std::copy(integers.cbegin(), integers.cend(), out);
    std::cout << "\n";

    std::cout << "First: " << integers.front() << ", Last: " << integers.back() << "\n";

    integers[0] = 7;
    integers.at(2) = 10;
    integers.insert(integers.cbegin() + 1, 22);

    std::cout << "Sau khi sua va chen 22: ";
    std::copy(integers.cbegin(), integers.cend(), out);
    std::cout << "\n";

    try {
        integers.at(100) = 999;
    } catch (const std::out_of_range &ex) {
        std::cout << "Bat ngoai le: out_of_range\n";
    }

    // Xoa phan tu dau tien
    integers.erase(integers.cbegin());
    std::cout << "Sau khi erase phan tu dau: ";
    std::copy(integers.cbegin(), integers.cend(), out);
    std::cout << "\n";

    // Xoa sach bang clear
    integers.clear();
    std::cout << "Sau clear, vector co rong khong: " << (integers.empty() ? "co" : "khong") << "\n";

    return 0;
}
